// Auto-generated by r2factor. Manual edits will be overwritten on next split.

use super::consts::MARKER_SCHWARZ_INTERFACE_MASS;
use super::consts::MARKER_SCHWARZ_INTERFACE_STIFFNESS;
use super::geometric::geometric_schwarz_interface_planes;
use super::geometric::geometric_schwarz_partitions;
use super::misc::artificial_schwarz_interface_faces;
use super::types::GeometricSchwarzTransmission;
use num_complex::Complex64;
use sonium_fem::assembly::{MassMatrix, assemble_face_mass, assemble_face_surface_stiffness};
use sonium_fem::mesh::Mesh;
use sonium_solvers::AdditiveSchwarzPreconditioner;

// Selection policy lives in `sonium_fem::backend_selection`; this module keeps
// the runner-local Schwarz helpers. (r2factor split output: keep this shim
// layout if the facade is re-split.)
pub use sonium_fem::backend_selection::FemPreconditionerKind;

pub(super) fn uses_geometric_schwarz_transmission(kind: FemPreconditionerKind) -> bool {
    matches!(
        kind,
        FemPreconditionerKind::Oras | FemPreconditionerKind::Habc
    )
}

pub(super) fn append_geometric_schwarz_boundary_matrices(
    mesh: &Mesh,
    kind: FemPreconditionerKind,
    boundary_matrices: &mut Vec<(usize, MassMatrix)>,
) -> Option<GeometricSchwarzTransmission> {
    if !uses_geometric_schwarz_transmission(kind) {
        return None;
    }

    let requested_subdomains =
        AdditiveSchwarzPreconditioner::<Complex64>::recommended_subdomain_count(mesh.num_nodes());
    if requested_subdomains < 2 {
        return None;
    }

    let planes = geometric_schwarz_interface_planes(mesh, requested_subdomains);
    if planes.is_empty() {
        return None;
    }

    let partitions = geometric_schwarz_partitions(mesh, &planes);
    let interface_faces = artificial_schwarz_interface_faces(mesh, &planes);
    if interface_faces.is_empty() {
        return None;
    }

    let face_count = interface_faces.len();
    let face_mass = assemble_face_mass(mesh, &interface_faces);
    if face_mass.nnz() == 0 {
        return None;
    }
    boundary_matrices.push((MARKER_SCHWARZ_INTERFACE_MASS as usize, face_mass));

    if kind == FemPreconditionerKind::Habc {
        let face_stiffness = assemble_face_surface_stiffness(mesh, &interface_faces);
        if face_stiffness.nnz() > 0 {
            boundary_matrices.push((MARKER_SCHWARZ_INTERFACE_STIFFNESS as usize, face_stiffness));
        }
    }

    Some(GeometricSchwarzTransmission {
        partitions,
        face_count,
    })
}
